// TH14 v1.00b / st05.ecl.txt MainSub05 766-783 reward wave.
// Card frame 0 = source entry (st05:766); source attack begins after the 120f opening buffer.
// Dependencies: GirlC01 st05:230-258, GirlC01_at 260-320, MainSub05b 785-797,
//               MainSub05c 799-813, Phantom03 1182-1205, Phantom03_at 1207-1248.
// F gates of enmCreateF/MF are omitted per approved reward-wave policy; mirror is explicit.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// TH14 type 20 -> OVAL, type 10 -> SHARD (synthetic alias table, touhou-bullets.ecl).
const TH14_OVAL: int = 672;
const TH14_SHARD: int = 512;

// 1/65536 and 1/32768 as fx, used to turn rand(65536) into the source RANDF / RANDF2 ranges.
const INV_65536: fx = 0.0000152587890625fx;
const INV_32768: fx = 0.000030517578125fx;

// st05:1230-1231: VELTIME(120) ramp to RANDF*0.3 keeping direction + ACCEL(120) 0.02 at 90deg.
// Both effects only last 120 frames, then the accumulated velocity is kept.
xformdef PHANTOM_ACCEL(delta: fx, ang: angle) {
    set_gravity(delta * cos(ang), delta * sin(ang) + 0.02fx);
    wait(120);
    set_gravity(0fx, 0fx);
}

// st05:1207-1248 Phantom03_at. 10 volleys, aimed relative to ABS_ANGLE with +-20deg random.
// ways: !E 1 / !N 1 / !H 2 / !LO 3 ; wait: !E 60 / other 30.
async sub phantom_fan(aabs: angle) {
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    if rank == RANK_HARD { ways = 2; }
    if rank == RANK_LUNATIC { ways = 3; }
    var interval: int = 30;
    if rank == RANK_EASY { interval = 60; }

    var vol: int = 0;
    while vol < 10 {
        // st05:1230 %RANDF * 0.3 sampled once per volley (shared by the volley).
        var ts: fx = ((rand(65536) as fx) * INV_65536) * 0.3fx;
        var delta: fx = (ts - 2.5fx) / 120fx;
        // st05:1232 angle = ABS_ANGLE + RANDF2*0.34906584, spread 0.34906584 (20deg).
        var r2: int = rand(65536) - 32768;
        var u2: fx = (r2 as fx) * INV_32768;
        var base: angle = aabs + (((u2 * 3641fx) as int) as angle);

        var q: int = 0;
        while q < ways {
            // Fixed-direction fan F(N,i): N=2 -> +10/-10, N=3 -> 0/-20/+20.
            var off: angle = 0deg;
            if ways == 2 {
                if q == 0 { off = 10deg; } else { off = -10deg; }
            }
            if ways == 3 {
                if q == 1 { off = -20deg; }
                if q == 2 { off = 20deg; }
            }
            var ba: angle = base + off;
            // st05:1226 ANIM a=1 keeps its 4*velocity retreat: 4*2.5 = 10px backward.
            _ = fire(TH14_SHARD, 6,
                     $self_x - 10fx * cos(ba), $self_y - 10fx * sin(ba),
                     2.5fx, ba, PHANTOM_ACCEL(delta, ba), none);
            q = q + 1;
        }
        vol = vol + 1;
        wait(interval);
    }
}

// st05:1182-1205 Phantom03.
// mirror 0 (left, enmCreateF) / mirror 1 (right, enmCreateMF): velocity angles are mirrored,
// bullet angles are explicit per side (source does not auto-mirror etAngle).
async sub phantom(mirror: int) {
    set_invuln(65535);
    set_hurtbox(14fx);   // st05:1186 setHurtbox(28,28) -> radius 14
    set_hitbox(8fx);     // st05:1187 setHitbox(16,16) -> radius 8

    var a0: angle = 45deg;        // st05:1190 moveVel(0.7853982, 4.0)
    var a1: angle = 0deg;         // st05:1191 moveVelTime(30,0,0.0,0.0)
    var aabs: angle = -2048bam;   // st05:1193 moveVel(-0.19634955, 0.0) -> -11.25deg
    if mirror == 1 {
        a0 = 135deg;
        a1 = 180deg;
        aabs = 34816bam;          // mirrored -11.25deg = 191.25deg
    }
    move_vel(0, a0, 4fx, EASE_LINEAR);
    move_vel(30, a1, 0fx, EASE_LINEAR);
    wait(30);
    move_vel(0, aabs, 0fx, EASE_LINEAR);

    // st05:1194-1196: ABS speed 0->2 quad-in over 240f while a REL circle (r -0.196->16 over
    // 80f, omega 1deg/f, radial 0) is added on top. The source Time omega target -999999 is
    // treated as the usual keep-current sentinel, so omega stays 1deg/f (see report).
    var theta: angle = rand(65536) as angle;   // st05:1195 %RANDRAD initial phase
    var r0: fx = -0.19634955fx;
    var dr: fx = (16fx - r0) / 80fx;
    var absx: fx = $self_x;
    var absy: fx = $self_y;
    move_to(0, absx + r0 * cos(theta), absy + r0 * sin(theta), EASE_LINEAR);

    spawn phantom_fan(aabs);   // st05:1197 async at t=30
    var k: int = 0;
    loop {
        k = k + 1;
        theta = theta + 1deg;
        var rr: fx = r0 + dr * (k as fx);
        if k > 80 { rr = 16fx; }
        var u: fx = 0fx;
        if k < 240 { u = (k as fx) / 240fx; }
        var spd: fx = 2fx;
        if k < 240 { spd = 2fx * u * u; }
        var ca: fx = cos(aabs);
        var sa: fx = sin(aabs);
        var nx: fx = absx + spd * ca + rr * cos(theta);
        var ny: fx = absy + spd * sa + rr * sin(theta);
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        absx = absx + spd * ca;
        absy = absy + spd * sa;
        wait(1);
    }
}

// st05:785-797 MainSub05b (left, mirror 0) and st05:799-813 MainSub05c (right, mirror 1):
// 7 each, every 80f; x = +-(192 + RANDF*32), y = 96 + RANDF*64.
async sub phantom_wave(mirror: int) {
    if mirror == 0 { spawn phantom_wave(1); }   // st05:788 c starts one frame after b
    var i: int = 0;
    while i < 7 {
        var rx: fx = (rand(65536) as fx) * INV_65536;
        var ry: fx = (rand(65536) as fx) * INV_65536;
        var px: fx = -192fx - rx * 32fx;
        if mirror == 1 { px = 192fx + rx * 32fx; }
        var py: fx = 96fx + ry * 64fx;
        _ = spawn_enemy(px, py, 100, 0, 1000, 0, phantom(mirror));
        i = i + 1;
        wait(80);
    }
}

// st05:260-320 GirlC01_at: 54 one-frame volleys (3 rounds x 18), angle sweeps by +-10deg,
// speed 3.0 down by 0.05 per volley, layer speeds first = B, last = 1.0 (M=1 Easy only B).
async sub girl_fan(f0: angle, f1: angle, layers: int) {
    var a: angle = aim_player() - f0;   // st05:290 %A = %ANGLE_PLAYER - %F0
    var spd: fx = 3fx;
    var round: int = 0;
    while round < 3 {                   // st05:292 $C = 2 -> 3 rounds
        var k: int = 0;
        while k < 18 {                  // $D/$E = 9 + 9
            var q: int = 0;
            while q < layers {
                var v: fx = spd;
                if q == 1 { v = 1fx; }  // st05:299 etSpeed(0,%B,1.0) last layer
                // etDist 16 minus the ANIM a=1 retreat 4*velocity.
                var d: fx = 16fx - 4fx * v;
                _ = fire(TH14_OVAL, 2,
                         $self_x + d * cos(a), $self_y + d * sin(a),
                         v, a, none, none);
                q = q + 1;
            }
            a = a + f1;
            spd = spd - 0.05fx;
            k = k + 1;
            wait(1);
        }
        round = round + 1;
    }
}

// st05:230-258 GirlC01.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // st05:239 setHurtbox(24,24)
    set_hitbox(8fx);     // st05:240 setHitbox(16,16)

    var a0: angle = 45deg;        // st05:241 moveVel(0.7853982, 4.0)
    var a1: angle = -45deg;       // st05:242 moveVelTime(80,1,-0.7853982,0.1)
    if mirror == 1 {
        a0 = 135deg;
        a1 = 225deg;              // mirrored -45deg
    }
    move_vel(0, a0, 4fx, EASE_LINEAR);
    move_vel(80, a1, 0.1fx, EASE_QUAD_IN);
    wait(60);                     // st05:243
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;           // st05:244 diffI($A,1,1,2,4)
    if rank == RANK_HARD { shots = 2; }
    if rank == RANK_LUNATIC { shots = 4; }
    var layers: int = 1;          // st05:265-273 etCount layers 1/2/2/2
    if rank != RANK_EASY { layers = 2; }
    var f0: angle = 90deg;        // st05:283-288 %F0/%F1 by $MIRROR
    var f1: angle = 10deg;
    if mirror == 1 {
        f0 = -90deg;
        f1 = -10deg;
    }
    var i: int = 0;
    while i < shots {
        spawn girl_fan(f0, f1, layers);   // st05:247 async
        i = i + 1;
        wait(180);                        // st05:248
    }
    move_vel(80, a1, 2fx, EASE_QUAD_IN);  // st05:251
    loop { wait(1000); }                  // st05:253-256
}

// st05:766-783 MainSub05: schedule the two phantom columns, then 4 girl pairs 120f apart.
// enmCreateF/MF are omitted as gates; the pair positions/HP/mirror are preserved.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn phantom_wave(0);                        // st05:769 async MainSub05b
    _ = spawn_enemy(-224fx, 128fx, 300, 0, 1000, 0, girl(0));   // st05:773 F, left
    wait(120);
    _ = spawn_enemy(224fx, 128fx, 300, 0, 1000, 0, girl(1));    // st05:775 MF, right
    wait(120);
    _ = spawn_enemy(-224fx, 128fx, 300, 0, 1000, 0, girl(0));   // st05:773
    wait(120);
    _ = spawn_enemy(224fx, 128fx, 300, 0, 1000, 0, girl(1));
    wait(120);
    _ = spawn_enemy(-224fx, 128fx, 300, 0, 1000, 0, girl(0));
    wait(120);
    _ = spawn_enemy(224fx, 128fx, 300, 0, 1000, 0, girl(1));
    wait(120);
    _ = spawn_enemy(-224fx, 128fx, 300, 0, 1000, 0, girl(0));
    wait(120);
    _ = spawn_enemy(224fx, 128fx, 300, 0, 1000, 0, girl(1));    // st05:779-781 final pair
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(1); }
}
